CREATE TABLE "User" ("id" TEXT NOT NULL,"name" TEXT NOT NULL,"email" TEXT NOT NULL,"passwordHash" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "User_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Link" ("id" TEXT NOT NULL,"shortCode" VARCHAR(12) NOT NULL,"originalUrl" TEXT NOT NULL,"userId" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Link_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Click" ("id" TEXT NOT NULL,"linkId" TEXT NOT NULL,"ipAddress" VARCHAR(64),"userAgent" TEXT,"referrer" TEXT,"device" VARCHAR(64),"browser" VARCHAR(64),"operatingSystem" VARCHAR(64),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "Click_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "User_email_key" ON "User"("email"); CREATE UNIQUE INDEX "Link_shortCode_key" ON "Link"("shortCode"); CREATE INDEX "Link_userId_createdAt_idx" ON "Link"("userId", "createdAt"); CREATE INDEX "Click_linkId_createdAt_idx" ON "Click"("linkId", "createdAt");
ALTER TABLE "Link" ADD CONSTRAINT "Link_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "Click" ADD CONSTRAINT "Click_linkId_fkey" FOREIGN KEY ("linkId") REFERENCES "Link"("id") ON DELETE CASCADE ON UPDATE CASCADE;
